This paper focuses on unconstrained stochastic DFO, wherein the objective function values are accessible only through a blackbox oracle corrupted by stochastic noise. We consider the problem 
\begin{equation}\label{probl1}
	\underset{\x\in\rn}{\min} f(\x), \qquad\mbox{with}\quad f(\x)=\Esp_{\ubar{\theta}}\left[f_{\ubar{\theta}}(\x)\right],
\end{equation}
%\quad\mbox{with}\quad f(\x)=\Esp_{\ubar{\theta}}\left[f_{\ubar{\theta}}(\x)\right]
where the values of the continuously differentiable function $f:\rn\to\R$ are available only via $f_{\ubar{\theta}}$, a stochastically noisy version of $f$, and where $\ubar{\theta}$ is a random variable whose distribution is possibly unknown. 


Unlike the stochastic trust-region framework STORM~\cite{blanchet2016convergence,chen2018stochastic}, which builds full space random models $\ubar{m}_k(\x)$, $\x\in\rn$, to approximate $f(\x)$, STARS operates as follows. On iteration $k$, given a current iterate $\xk$, let $\mathcal{Y}_k\subseteq \rn$ be the affine space randomly chosen through the range of a matrix $\Qk\in\rnp$ 
%satisfying $\norme{\Qk}\leq\Qmax$ for some $\Qmax>0$, 
whose entries are randomly selected; that is, 
\[\mathcal{Y}_k = \accolade{\xk+\Qk\bm{{\s}}:\bm{{\s}}\in\R^p}.\]
Then, given a trust-region radius $\dk>0$, a subspace model $\mhatk(\s), \s\in\rp$ is built only on $\mathcal{Y}_k$ using realizations of the stochastically noisy function $f_{\ubar{\theta}}$; the model  serves as an approximation of $f(\x)$ in $\mathcal{B}(\xk,\dk;\Qk):=\accolade{\xk+\Qk\s \in \mathcal{Y}_k:\normii{\s}\leq\dk}$. For concreteness, here we employ a quadratic subspace model given by 
\begin{equation*}
f(\xk+\Qk\s)\approx\mhatk(\bm{\s}):= f_k+\gkhat^\top\s+\s^\top\Hkhat\s,
\end{equation*}
where $\gkhat\in \R^p$ and $\Hkhat\in \Sym^{p}$ are the low-dimensional model gradient and Hessian, respectively. A {\it tentative step} $\Qk\sk\in\rn$ is produced by using the solution $\sk\in\rp$ obtained by approximately minimizing $\mhatk$ inside the trust  region; that  is, $\sk\approx{\argmin}\left\{ \mhatk(\s): \s\in\rp, \, \normii{\bm{{\s}}}\leq \dk\right\}$. Inspired by~\cite{CRsubspace2021,chen2018stochastic}, the {\it trial step} $\sk$ has to provide a sufficient decrease in $\mhatk$ by satisfying the following standard fraction of the Cauchy decrease condition.

\begin{assumption}
For every iteration $k$, a trial step $\sk\in\rp$ is computed so that\footnote{Throughout the manuscript, the matrix norm $\norme{\cdot}$ is supposed to be {\it consistent} with the Euclidean norm; that is, $\normii{\Ab\xb}\leq \norme{\Ab}\normii{\xb}$, which holds for both Frobenius and spectral matrix norms.}
\begin{equation}\label{CauchyDecrease}
\mhatk(\bm{0})-\mhatk(\bm{\sk})\geq \frac{\kappa_{fcd}}{2}\normii{\gkhat}\min\accolade{\dk,\frac{\normii{\gkhat}}{\max\left(\norme{\Hkhat},1\right)}},
\end{equation}
for some constant $\kappa_{fcd}\in (0,1]$.
\end{assumption}


The random variables considered here are all defined on the same probability space $(\Omega,\F, \pr)$, where $\Omega$, referred to as the {\it sample space}, is a nonempty set whose elements $\omega$ and subsets are called {\it sample points} and {\it events}, respectively. $\F$ is a collection of such events, which is called a {\it $\sigma$-algebra}. $\pr$ is a finite measure defined on the measurable space $(\Omega,\F)$, satisfying $\prob{\Omega}=1$ and referred to as the {\it probability measure}. An increasing subsequence $\accolade{\mathcal{S}_k}_k$ of $\sigma$-algebras of $\F$ will be called a {\it filtration}. Let $\mathscr{B}(\rn)$ be the $\sigma$-algebra generated by the open sets of $\rn$, also known as the Borel $\sigma$-algebra of $\rn$. A random variable $\ubar{z}$ is a measurable map defined on $(\Omega,\F, \pr)$ into the measurable space $(\rn, \mathscr{B}(\rn))$, where measurability means that $\accolade{\ubar{z}\in A}:=\accolade{\omega\in\Omega:\ubar{z}(\omega)\in A} =:{\ubar{z}}^{-1}(A)\in\F\ \forall A\in \mathscr{B}(\rn)$~\cite{bhattacharya2007basic}. For the remainder of the manuscript, vectors will be written in lowercase boldface (e.g., $\x\in\rn, n\geq 2$) while matrices will be written in uppercase boldface (e.g., $\Qk\in\rnp$), and underlined letters (e.g., $\ubar{z}, \ubar{\x}, \QkRandom$) will be used to denote random quantities; $z=\ubar{z}(\omega)$ will denote a realization of $\ubar{z}$.


\begin{algorithm}[htb]
\caption{STARS}
\label{algoStoScalTR} 
\textbf{[0] Initialization}\\
\hspace*{10mm}Choose constants $\gamma>1$, $\eta_1\in(0,1)$, $\eta_2>0$, $j_{\max}\in\N$, $\varepsilon\in(0,1)$, $\beta\in(0,1)$, \\ 
\hspace*{10mm}$c_1\geq 1$, initial trust-region radius $\delta_0>0$, and maximum trust-region radius\\
\hspace*{10mm}$\dmaxx=\gamma^{j_{\max}}\delta_0$, starting point $\bm{{\x}_0}\in\rn$, and dimension $p\in\intbracket{1,n}$.\\ 
\hspace*{10mm}Set the iteration counter $k \gets 0$.\\
\textbf{[1] Construction of subspace model}\\
\hspace*{10mm}Generate $\Qk$: a realization of a\footnotemark {\em WAM}($1-\varepsilon,\beta$), using a distribution $\mathbb{Q}_{k}$.\\
\hspace*{10mm}Build model $\mhatk:\rp\to\R$ that is $(\kef,\keg;\Qk)$-fully linear 
%$\mhatk(\s)={\f}_k+\gkhat^{\top}\s+$\\
%\hspace*{10mm}$\frac{1}{2}\s^{\top}\Hkhat\s\approx f(\xk+\Qk \s)$, that locally approximates $f$ 
in  $\mathcal{B}(\xk,c_1\dk;\Qk)$.\\ 
%\hspace*{10mm}with the affine space defined by the columns of $\Qk$.\\
\textbf{[2] Step calculation}\\
\hspace*{10mm}Compute $\sk\approx {\argmin}\left\{ \mhatk(\s) : \; \s\in\rp:\normii{\s}\leq \dk\right \}$ satisfying~\eqref{CauchyDecrease}.\\
\textbf{[3] Estimate computation}\\
\hspace*{10mm}Obtain estimates $\fok\approx f(\xk)$ and $\fsk\approx f(\xk+\Qk\sk)$ satisfying~\eqref{accEstimates}.\\
\textbf{[4] Updates}\\
\hspace*{10mm}Compute $\rho_k=\frac{\fok-\fsk}{\mhatk(\bm{0})-\mhatk(\sk)}.$\\
\hspace*{10mm}If $\rho_k\geq \eta_1$ and $\normii{\gkhat}\geq \eta_2\dk$ (\textbf{success}): \\
\hspace*{16mm}set $\bm{\xkun}=\xk+\Qk\sk$ and $\dkun=\min\accolade{\gamma\dk,\dmaxx}$. \\
\hspace*{10mm}Otherwise (\textbf{failure}): set $\bm{\xkun}=\xk$ and $\dkun=\gamma^{-1}\dk$.\\
\hspace*{10mm}Update the iteration counter $k \gets k+1$, and go to~\textbf{[1]}.\\
\end{algorithm}
%\caption[]{\small{STARS algorithm}}
%\end{figure*}
\footnotetext{See Definition~\ref{wellAlignedDefinition} for the meaning of {\em WAM}($1-\varepsilon,\beta$).}


The deterministic models $\mhatk$ and the function estimates $\fok$ and $\fsk$ are constructed by using evaluations of the noisy function $f_{\ubar{\theta}}$ and the randomly selected entries of the deterministic matrix~$\Qk=\QkRandom(\omega)$.  Hence, $\mhatk$, $\fok$, and $\fsk$ can be considered as realizations of random models and estimates $\Mhatk$, $\Fok$, and $\Fsk$, respectively. Each iteration of Algorithm~\ref{algoStoScalTR} is therefore influenced by the behavior of these random quantities; and consequently, the algorithm results in a stochastic process. The present work shows that under certain conditions on the sequences~$\accoladekinN{\QkRandom}$, $\accoladekinN{\Fok,\Fsk}$, and $\accoladekinN{\Mhatk}$, the resulting stochastic process has desirable convergence properties, conditioned on the past, where {\it past} means the {\it past history} of the algorithm (see~Remark~\ref{whyTheseSigmaAlgebras}). In particular, for the needs of convergence and expected complexity analyses presented  in Sections~\ref{Section4} and~\ref{Section5}, and as will be seen  in Section~\ref{Section3}, the random models~$\Mhatk$ and estimates~$\Fok,\Fsk$ are required to be probabilistically sufficiently accurate conditioned on the past, as was the case in~\cite{chen2018stochastic}. Moreover, $\QkRandom$ must guarantee a high quality of the selected subspace probabilistically and conditioned on the past, as will be detailed in Section~\ref{Section31}. 

For all $k\in\N$, denote by $(\QkRandom)_{ij},  (i,j)\in \intbracket{1,n}\times\intbracket{1,p}=:\mathbb{I}_{n,p}$ the entries of the random matrix $\QkRandom$, where for $a\leq b$, $\intbracket{a,b}:=[a,b]\cap\mathbb{Z}$  throughout the manuscript. 
To formalize conditioning on the past, we consider the three filtrations $\accolade{\falgebra}_{k\in\N}$, $\accolade{\fqalgebra}_{k\in\N}$, and $\accolade{\fmqalgebra}_{k\in\N}$ defined respectively by 
\begin{equation*}
\begin{array}{rcl}
\falgebra &:=& \sigma\left(\Foell, \Fsell, \Mhatell,  (\QellRandom)_{ij} \mbox{ with}\  \ell \in \intbracket{0,k-1} \mbox{ \&}\ (i,j)\in \mathbb{I}_{n,p} \right)\\
\fqalgebra &:=& \sigma\left(\Foell, \Fsell, \Mhatell, (\QellRandom)_{ij}, (\QkRandom)_{ij} \mbox{ with}\  \ell \in \intbracket{0,k-1} \mbox{ \&}\ (i,j)\in \mathbb{I}_{n,p} \right)\\
\fmqalgebra &:=& \sigma\left(\Foell, \Fsell, \Mhatell, (\QellRandom)_{ij}, (\QkRandom)_{ij}, \ \Mhatk \mbox{ with}\  \ell \in \intbracket{0,k-1} \mbox{ \&}\ (i,j)\in \mathbb{I}_{n,p}  \right).
\end{array}
\end{equation*}
% \begin{eqnarray*}
%  \falgebra &:=& \sigma\left(\Foell, \Fsell, \Mhatell\ \mbox{and}\ (\QellRandom)_{ij}\ \mbox{with}\  \ell \in \intbracket{0,k-1}\ \mbox{and}\ (i,j)\in \mathbb{I}_{n,p}\right)\\
%  \fqalgebra &:=& \sigma\left(\Foell, \Fsell, \Mhatell,\ (\QellRandom)_{ij}\ \mbox{and}\ (\QkRandom)_{ij}\ \mbox{with}\  \ell \in \intbracket{0,k-1}\ \mbox{and}\ (i,j)\in \mathbb{I}_{n,p}\right)\\
%  \fmqalgebra &:=& \sigma\left(\Foell, \Fsell, \Mhatell,\ (\QellRandom)_{ij},\ \Mhatk\ \mbox{and}\ (\QkRandom)_{ij}\ \mbox{with}\  \ell \in \intbracket{0,k-1}\ \mbox{and}\ (i,j)\in \mathbb{I}_{n,p}\right).
% \end{eqnarray*}
Here, for {\it completeness}~\cite{billingsley1995ThirdEdition}, $\mathcal{F}_{-1}=\sigma(\bm{\x_0})$.
%One can easily see that . 
By construction, $\falgebra\subset\fqalgebra\subset\fmqalgebra$, $\QkRandom$ is both~$\fqalgebra$ and~$\fmqalgebra$-measurable, and $\Mhatk$ is~$\fmqalgebra$-measurable, which imply that $\E{\QkRandom|\fqalgebra}=\E{\QkRandom|\fmqalgebra}=\QkRandom$ and $\E{\Mhatk|\fmqalgebra}=\Mhatk$. 
%The  motivation for  introducing these $\sigma$-algebras in the formalization of conditioning on the past is explained next.

\begin{remark}\label{whyTheseSigmaAlgebras}
At a given iteration~$k$, when generating~$\QkRandom$, because no model or estimates were generated since the start of the iteration, it obviously follows from the construction of Algorithm~\ref{algoStoScalTR} that its past history can be formalized by~$\falgebra$. On the other hand, when constructing~$\Mhatk$, the past of the algorithm that includes~$\QkRandom$, given that the latter is already generated since the beginning of iteration~$k$, can therefore be formalized by~$\fqalgebra$. A similar observation  explains why~$\fmqalgebra$ can formalize the past history of Algorithm~\ref{algoStoScalTR} before the construction of~$\Fok$ and~$\Fsk$. These observations will also play an important role in the formalization of sufficient accuracy of the random models and estimates in Definitions~\ref{defProbQkfully} and~\ref{defProbAccEstim} and the formalization of high quality of the random subspaces in Assumption~\ref{wellAlignedAssumption}.  
\end{remark}


Recalling Remark~\ref{whyTheseSigmaAlgebras} and inspired by~\cite{CRsubspace2021}, we propose a probabilistic quantification of the quality of the subspace selection as follows.

\begin{definition}\label{wellAlignedDefinition}
For fixed $\alpha_Q,\beta_Q\in (0,1)$, a sequence $\accoladekinN{\QkRandom}$ of random matrices 
%determining the selection of subspaces 
is $(1-\beta_Q)$-probabilistically $\alpha_{Q}$-well aligned if, for any $\F_{k-1}$-measurable random vector $\viRandom$ with realizations $\vi\in \rn$, the events 
$\mathcal{A}_k:= \accolade{\normii{\QkRandomTranspose\viRandom}\geq \alpha_{{Q}}\normii{\viRandom}}$ satisfy 
\begin{equation}\label{Akineq}
\prob{\mathcal{A}_k|\F_{k-1}}=\E{\iak|\F_{k-1}}\geq 1-\beta_Q,
\end{equation}
where $\iak$ denotes the indicator function of the event $\mathcal{A}_k$; that  is, $\iak(\omega)=1$ if $\omega\in \mathcal{A}_k$ and $\iak(\omega)=0$ otherwise. Random matrices satisfying~\eqref{Akineq} will be referred to as {WAM}($\alpha_Q,\beta_Q$).
%, in other words, well-aligned matrices with parameters $\alpha_Q$ and $\beta_Q$.
\end{definition}
%\begin{definition}
%Random matrices satisfying the conditions of Lemma... with parameters $\varepsilon, \beta$ will be referred to as a {\em JLM}($\varepsilon,\beta$), i.e., Johnson-Lindenstrauss matrices with parameters~$\varepsilon$ and~$\beta$.
%\end{definition}
For convergence purposes  in Sections~\ref{Section4} and~\ref{Section5}, the following will be assumed throughout the manuscript.
\begin{assumption}\label{wellAlignedAssumption}
The sequence $\accoladekinN{\QkRandom}$ of matrices used by Algorithm~\ref{algoStoScalTR} is $(1-\beta_Q)$-probabilistically $\alpha_{Q}$-well aligned for some fixed $\alpha_Q\in (0,1)$ and $\beta_Q\in (0,1/2)$.
\end{assumption}


Inspired by~\cite{CRsubspace2021}, a technical assumption needed for convergence and expected complexity analyses later in Sections~\ref{Section4} and~\ref{Section5} is the following. 
\begin{assumption}\label{QmaxAssumption}
Any realization $\Qk$ of the random matrix used by Algorithm~\ref{algoStoScalTR} satisfies $\norme{\Qk}\leq \Qmax$ for all $k\in\N$, for some constant $\Qmax >0$ independent of~$k$.
\end{assumption}


\subsection{Probabilistic models and estimates in random subspaces.}
As mentioned at the beginning of Section~\ref{Section3}, the models used by Algorithm~\ref{algoStoScalTR} need to be sufficiently accurate. Motivated by~\cite{chen2018stochastic}, this sufficient accuracy is formalized for deterministic subspace models by the following measure of accuracy inspired by~\cite{CRsubspace2021}.
\begin{definition}\label{QkFullyLinearModels}
Assume $\nabla f$ is  Lipschitz continuous. Given $\Qk\in\rnp$ and $\xk\in\rn$, a function $\mhatk:\rp\to\R$ is a $(\kef,\keg; \Qk)$-fully linear model of $f$ in $\mathcal{B}(\xk,\dk;\Qk)$ for some $\dk>0$ if there exist constants $\kappa_{ef}, \kappa_{eg} >0$ independent of $k$ such that for all $\s\in\rp$ with $\normii{\s}\leq \dk$,
\begin{equation}\label{Eq36}
%\begin{split}
\abs{f(\xk +\Qk\s)-\mhatk(\s)}\leq \kappa_{ef}\dk^2\quad \mbox{and}\quad
\normii{\Qk^{\top}\nabla f(\xk +\Qk\s)-\nabla\mhatk(\s)}\leq \kappa_{eg}\dk.
%\end{split}
\end{equation}
\end{definition}
As pointed out in~\cite{CRsubspace2021}, the gradient condition in~\eqref{Eq36} is due to the fact that given any fixed~$\x$ and~$\Q$, if $\hat{f}(\s):=f(\x+\Q\s)$, then $\nabla_{\s} \hat{f}(\s)=\Q^{\top}\nabla_{\x} f(\x+\Q\s)$. Moreover, denoting by $\bm{I}$ the identity matrix in full-dimensional subspaces where $p=n$, then $(\kef,\keg; \bm{I})$-fully linear models correspond to standard fully linear models~\cite[Definition~6.1]{CoScVibook}.

%Inspired by~\cite{chen2018stochastic}, and 
Recalling Remark~\ref{whyTheseSigmaAlgebras}, the next definition formalizing sufficient accuracy of probabilistic subspace models $\Mhatk$ is a stochastic variant of Definition~\ref{QkFullyLinearModels}, which generalizes~\cite[Definition~3.4]{chen2018stochastic} to low-dimensional subspaces. The existence of such models will be rigorously demonstrated  in Theorem~\ref{subspaceModel1} and Corollary~\ref{CorQkFully}.
\begin{definition}\label{defProbQkfully}
A sequence $\accolade{\Mhatk}$ of random models is $\beta_m$-probabilistically \\ $(\kef,\keg; \Qk)$-fully linear with respect to the random sequence $\accolade{\mathcal{B}(\Xk,\Dk;\QkRandom)}$ if the events
\[I_k^Q=\accolade{\mbox{Given}\ \Qk\ \mbox{and}\ \xk, \Mhatk\ \mbox{is}\ (\kef,\keg;\Qk)\mbox{-fully linear for}\ f\ \mbox{in}\ \mathcal{B}(\Xk,\Dk;\QkRandom)}\]
satisfy the supermartingale-like condition
\begin{equation}\label{ikQProb}
\prob{I^Q_k|\fqalgebra}=\E{\iik|\fqalgebra}\geq \beta_m.
\end{equation}
\end{definition}
Recalling that estimates of unknown function values also need to be sufficiently accurate, we introduce a formalization of sufficient accuracy inspired by~\cite{audet2019stomads,chen2018stochastic,dzahini2020expected,dzahini2020constrained,paquette2018stochastic} and motivated by~\cite{CRsubspace2021} as follows.
\begin{definition}
Given $\ef>0$ and $\Qk\sk\in\rn, \, \xk\in\rn$, $\fok$ and $\fsk$ are called $\ef$-accurate estimates of $f(\xk)$ and $f(\xk+\Qk\sk)$, respectively, for a given $\dk$ if
\begin{equation}\label{accEstimates}
\abs{\fok-f(\xk)}\leq\ef\dk^2\quad \mbox{ and }\quad  \abs{\fsk-f(\xk+\Qk\sk)}\leq\ef\dk^2.
\end{equation}
\end{definition}


Recalling Remark~\ref{whyTheseSigmaAlgebras},
%and following~\cite{audet2019stomads,chen2018stochastic,dzahini2020expected,dzahini2020constrained,paquette2018stochastic}, 
we  extend  this definition to the following stochastic variant.
\begin{definition}\label{defProbAccEstim}
A sequence of random estimates $\accolade{\Fok,\Fsk}$ is said to be $\beta_f$-probabilistically $\ef$-accurate with respect to the corresponding sequence $\accolade{\Xk,\Dk,\QkRandom\Sk}$ if the events 
\begin{eqnarray*}
J_k^Q &=&\left\lbrace\mbox{Given}\ \Qk\ \mbox{and}\ \xk, \Fok \mbox{ and } \Fsk \mbox{ are }\ef\mbox{-accurate estimates of } f(\xk)  \mbox{ and}\right.\\
& &\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad \left.  f(\xk+\Qk\sk), \mbox{ respectively, for } \Dk \right\rbrace
\end{eqnarray*}
% 
satisfy the supermartingale-like condition
$\prob{J^Q_k|\fmqalgebra}\geq \beta_f.$
\end{definition}


Based on Definitions~\ref{wellAlignedDefinition}, \ref{defProbQkfully}, and~\ref{defProbAccEstim}, {\it true} iterations, in other words, those for which $\iak\iik\ijk=1$, occur with a total probability of at least $\tilde{\beta}:=\beta_f\beta_m(1-\beta_Q)$ conditioned on $\falgebra$. Noting that by construction $\iak$ is both $\fqalgebra$-measurable and $\fmqalgebra$-measurable since $\fqalgebra\subset\fmqalgebra$, and that $\iik$ is $\fmqalgebra$-measurable, then for $F:= \accolade{\mathcal{A}_k\cap I^Q_k\cap J_k^Q}$, we have
\begin{equation}\label{prodBetaIneq}
\begin{split}
\pr(F|\falgebra)&=\E{\iak\iik\ijk|\falgebra}
=\E{\iak\iik\E{\ijk|\fmqalgebra} |\falgebra}\\
&\geq \beta_f\E{\iak\E{\iik|\fqalgebra} |\falgebra}\geq \beta_f\beta_m\E{\iak|\falgebra}\geq \tilde{\beta}.
%&\geq \beta_f\beta_m(1-\beta_Q),
\end{split}
\end{equation}
The second equality and the first two inequalities used the  {\it William's Tower Property} for conditional expectations~\cite[Theorem~34.4.]{billingsley1995ThirdEdition}, namely, the fact that if ${\ubar{z}}$ is integrable and the $\sigma$-algebras $\mathcal{G}_1$ and $\mathcal{G}_2$ satisfy $\mathcal{G}_1\subset\mathcal{G}_2$, then $\E{{\ubar{z}}|\mathcal{G}_1}=\E{\E{{\ubar{z}}|\mathcal{G}_2}|\mathcal{G}_1}$. Moreover, for a $\sigma$-algebra $\mathcal{G}$,  $\E{{\ubar{r}}{\ubar{u}}|\mathcal{G}}={\ubar{r}}\E{{\ubar{u}}|\mathcal{G}}$ if~${\ubar{r}}$ is $\mathcal{G}$-measurable and~${\ubar{r}}$ and~${\ubar{r}}{\ubar{u}}$ are integrable~\cite[Theorem~34.3.]{billingsley1995ThirdEdition}.

Note that even though the present algorithmic framework does not distinguish true iterations from {\it false} ones, it holds that $\prob{\underset{k\to\infty}{\limsup}\ \ubar{w}_k=\infty}=1$, where
\begin{equation}\label{randomWalk}
\ubar{w}_k:=\sum_{i=0}^k\left(2\mathds{1}_{\mathcal{A}_i}\mathds{1}_{I^Q_i}\mathds{1}_{J^Q_i}-1\right),
\end{equation}
as will be seen later in the proof of Theorem~\ref{liminfTheorem} provided $\tilde{\beta}>1/2$. This shows that true iterations occur sufficiently often for the convergence of Algorithm~\ref{algoStoScalTR} to hold (see, e.g.,~\cite[Theorem~3.6]{dzahini2020constrained} for a similar result).


\begin{remark}%\label{remarkProdBetafBetam}
Calculations similar to those in~\eqref{prodBetaIneq} easily yield 
\begin{eqnarray}\label{prodBetafBetam}
\prob{I^Q_k\cap J_k^Q|\fqalgebra}\geq \beta_f\beta_m, & & \prob{J_k^Q|\fqalgebra}\geq \beta_f,\\
%\end{equation}
%\begin{equation}
\label{otherProbIneqs}
\prob{I^Q_k|\falgebra}\geq\beta_m & \qquad \mbox{ and } \qquad & \prob{J^Q_k|\falgebra}\geq\beta_f,
\end{eqnarray}
which will be useful in the proofs of Theorems~\ref{zerothOrderScal} and~\ref{liminfTheorem}, respectively. 
%and as was considered in~\cite[Theorems~4.11]{chen2018stochastic} in similar situations.
\end{remark}


In the remainder of the manuscript, the following inspired by~\cite[Assumptions~4.1 and~4.3]{chen2018stochastic}, respectively, will be assumed.
\begin{assumption}\label{fGradfAssumption}
For given $\bm{\x_0}$, $\dmaxx$, and $\bm{Q_0}$, let $\mathscr{L}(\bm{\x_0};\bm{Q_0})\subset\rn$ be the set containing all iterates of Algorithm~\ref{algoStoScalTR}. Define the region $\mathscr{L}^{\star}(\bm{\x_0};\bm{Q_0})$ considered by the algorithm realizations as $\mathscr{L}^{\star}(\bm{\x_0};\bm{Q_0})=\ds{\underset{\accolade{k\, \geq\, 0,\, \xk\in\mathscr{L}(\bm{\x_0};\bm{Q_0})}}{\bigcup}}\mathcal{B}(\xk,\dmaxx;\Qk)$. Then $f(\x)\geq f_{\min}$ for all $\x\in\rn$ and for some constant $f_{\min}>-\infty$. Moreover, $f$ and its gradient are Lipschitz continuous on $\mathscr{L}^{\star}(\bm{\x_0};\bm{Q_0})$.
\end{assumption}

\begin{assumption}\label{boundedHessian}
There exists some $\kappa_h\geq 1$ such that for all $k\geq 0$, the Hessian $\Hkhat$ of all realizations of $\Mhatk$ satisfies $\norme{\Hkhat}\leq \kappa_h.$
\end{assumption}


\begin{lemma}\label{LemmaC}
Let Assumption~\ref{boundedHessian} hold. Assume that $\mhatk$ is $(\kef,\keg;\Qk)$-fully linear and the estimates $\accolade{\fok,\fsk}$ are $\ef$-accurate with $\ef\leq\kappa_{ef}$. Then the $k$th iteration is successful if 
\begin{equation}\label{deltaLemmaC}
\dk\leq\min\accolade{\frac{1}{\kappa_h}, \frac{1}{\eta_2}, \frac{\kappa_{fcd}(1-\eta_1)}{8\kappa_{ef}}}\normii{\gkhat}.
\end{equation}
\end{lemma}

\begin{lemma}\label{LemmaD}
Suppose that Assumption~\ref{boundedHessian} holds and the estimates $\accolade{\fok,\fsk}$ are $\ef$-accurate with $\ef<\frac{1}{4}\eta_1\eta_2\kappa_{fcd}\min\accolade{\frac{\eta_2}{\kappa_h}, 1}$. If the $k$th iteration is successful, then the improvement in $f$ is such that
\begin{equation}\label{LemmaDimprovement}
f(\xkun)-f(\xk)\leq -C_2\dk^2,
\end{equation}
where $C_2=\frac{1}{2}\eta_1\eta_2\kappa_{fcd}\min\accolade{\frac{\eta_2}{\kappa_h}, 1} -2\ef>0$. 
\end{lemma}

\subsection{Zeroth-order convergence result.}\label{Section4p2}
To prove in Theorem~\ref{zerothOrderScal} that the sequence of random trust-region radii converges to zero almost surely, we assume the following.
\begin{assumption}\label{assumptionsOnEstimatesAndModels} 
The sequences of estimates $\accolade{\Fok, \Fsk}$ and models $\accolade{\Mhatk}$ generated by Algorithm~\ref{algoStoScalTR} are, respectively, $\beta_f$-probabilistically $\ef$-accurate for 
$\ef<\min\accolade{\kappa_{ef}, \frac{1}{4}\eta_1\eta_2\kappa_{fcd}\min\accolade{\frac{\eta_2}{\kappa_h}, 1}}$ and $\beta_m$-probabilistically $(\kef,\keg;\Qk)$-fully linear for some $\beta_f, \beta_m\in (0,1)$.
\end{assumption}


A formal definition from~\cite{blanchet2016convergence} of the stopping time related to a discrete time stochastic process is as follows.
\begin{definition}
A random variable~$\tauEpsilon$ is called a stopping time with respect to a given discrete time stochastic process $\accolade{\X_k}_{k\in\N}$ if the event $\accolade{\tauEpsilon=k}$ belongs to the $\sigma$-algebra $\sigma\left(\X_1,\dots,\X_k \right)$ generated by $\X_1,\dots,\X_k$, for each $k\in\N$.
\end{definition}

Consider a stochastic process $\accolade{\left(\Phik,\Dk\right)}_{k\in\N}$, where $\Phik, \Dk\in [0,\infty)$, and introduce on the same probability space as $\accolade{\left(\Phik,\Dk\right)}_{k\in\N}$ a biased random walk process $\accolade{\Wtildek}_{k\in\N}$ obeying the following dynamics:
\begin{equation}\label{dynamicsWk}
\prob{\Wtildekun=1|\F_k}=q\qquad \mbox{ and }\qquad \prob{\Wtildekun=-1|\F_k}=1-q,
\end{equation}
where $q\in (1/2, 1)$ and $\F_k=\sigma\left( \left(\PhiZero,\Dzero,\WtildeZero\right),\dots,\left(\Phik,\Dk,\Wtildek\right) \right)$, with ${\WtildeZero=1}$.

Let $\accolade{\tauEpsilon}_{\epsilon>0}$ be a family of stopping times with respect to $\accoladekinN{\F_k}$, parameterized by $\epsilon$. A bound on $\E{\tauEpsilon}$ is derived in~\cite{blanchet2016convergence,dzahini2020expected,paquette2018stochastic} under the following assumption.

\begin{assumption}\label{assumptionRenewal}
The following hold for the stochastic process $\accoladekinN{\left(\Phik,\Dk,\Wtildek\right)}$.
\begin{itemize}
\item[(i)] There exist $\lambda\in (0, \infty)$ and $\dmaxx=\delta_0 e^{\lambda j_{\max}}$ for some $j_{\max}\in\Z$ such that $\Dk\leq \dmaxx$ for all $k$.
\item[(ii)] There exists $\depsilon=\delta_0 e^{\lambda j_{\epsilon}}$, for some $j_{\epsilon}\in\Z$ with $j_{\epsilon}\leq 0$ such that for all $k$
\begin{equation}\label{dynamicsRenewal}
\itksup\Dkun\geq \itksup\min\accolade{\Dk e^{\lambda\Wtildekun}, \depsilon}, 
\end{equation}
where $\Wtildekun$ satisfies~\eqref{dynamicsWk}. 
\item[(iii)] There exists a nondecreasing function $h:[0,\infty)\to (0,\infty)$ and a constant $\varrho>0$ such that for all $k$
\[\E{\Phikun-\Phik|\F_k}\itksup\leq-\varrho h\left(\Dk\right)\itksup.\]
\end{itemize}
\end{assumption}

Noticing that the event $\accolade{\Dk\geq\depsilon}$ occurs sufficiently frequently on average, often $\E{\Phikun-\Phik}$ can be bounded by some negative fixed constant \cite{blanchet2016convergence}, thus allowing a bound on the expected stopping time $\E{\tauEpsilon}$, as stated next.

\begin{theorem}\label{theorComplexity1}
Under Assumption~\ref{assumptionRenewal}, 
$\E{\tauEpsilon}\leq \frac{q}{2q-1}\cdot\frac{\PhiZero}{\varrho h\left(\depsilon\right)}+1.$
\end{theorem}


\subsection{Expected complexity result.}\label{ExpectedSubsection}

Consider the process $\accolade{\left(\Phik,\Dk,\Wtildek\right)}_{k\in\N}$, where~$\Phik$ is defined in Theorem~\ref{zerothOrderScal}, $\Dk$ is the trust-region radius, and $\Wtildek$ is  defined by $\Wtildek=2\left(\iak\iik\ijk-\frac{1}{2} \right)$.  Given $\epsilon\in (0,1)$, let $\tauEpsilon$ be the number of iterations required by Algorithm~\ref{algoStoScalTR} to first drive the norm of the gradient of~$f$ below $\epsilon$:  
\[\tauEpsilon:=\inf \accolade{k\in\N: \normii{\nabla f(\Xk)}\leq\epsilon}.\]
Then $\tauEpsilon$ is a stopping time for the stochastic process generated by Algorithm~\ref{algoStoScalTR}, and hence for $\accolade{\left(\Phik,\Dk,\Wtildek\right)}_{k\in\N}$ \cite{blanchet2016convergence,dzahini2020expected,paquette2018stochastic}. More precisely, the occurrence of $\accolade{\tauEpsilon=k}$ can be determined by observing $\left(\PhiZero,\Dzero,\WtildeZero\right)$, $\dots$ $(\Phikmun,\Dkmun,\Wtildekmun)$, which means that $\tauEpsilon$ is a stopping time with respect to the filtration $\accoladekinN{\falgebra}$. To bound $\E{\tauEpsilon}$ using Theorem~\ref{theorComplexity1}, we show next that Assumption~\ref{assumptionRenewal} holds for $\accolade{\left(\Phik,\Dk,\Wtildek\right)}_{k\in\N}$.


From~\eqref{PhikIncrementBound}, since $\falgebra\subset\fqalgebra$, we observe that\footnote{Unlike the analysis in~\cite{blanchet2016convergence}, the first equality of~\eqref{PhikIncrSecond} is essential and due to the fact that in the present framework $\tauEpsilon$ is a stopping time with respect to $\sigma$-algebras $\falgebra$ that are smaller than $\fqalgebra$ with respect to which $\accoladekinN{\Phik}$ was proved in Theorem~\ref{zerothOrderScal} Eq.~\eqref{PhikIncrementBound} to be a supermartingale.} for all $k\in\N$:
\begin{equation}\label{PhikIncrSecond}
\E{\Phikun-\Phik|\falgebra}=\E{\E{\Phikun-\Phik|\fqalgebra}|\falgebra}\leq\E{-\varrho\Dk^2|\falgebra}=-\varrho\Dk^2.
\end{equation}
Note that~\eqref{PhikIncrSecond} holds for any realizations of the random variables $\E{\Phikun-\Phik|\falgebra}$ and $\Dk^2$ and hence on the event $\accolade{\tauEpsilon >k}$ in particular, which shows that Assumption~\ref{assumptionRenewal}-$(iii)$ holds with the constant $\varrho=\frac{1}{2}\beta_f(1-\nu)(1-\frac{1}{\gamma^2})$ of Theorem~\ref{zerothOrderScal} and $h(t)=t^2$. Assumption~\ref{assumptionRenewal}-$(i)$ automatically follows from the initialization strategy in Algorithm~\ref{algoStoScalTR} with $\lambda=\ln(\gamma)$. Before showing by means of Lemma~\ref{smallLemma}, inspired by~\cite[Lemma~7]{blanchet2016convergence}, that~\eqref{dynamicsRenewal} is satisfied, we first define the constant 
\begin{equation}\label{deltaEpsilonDefinition}
\depsilon:=\frac{\epsilon}{\xi}, \quad\mbox{with } \xi\geq  \frac{1}{\alpha_Q}\max\accolade{\kappa_h+\kappa_{eg}, \eta_2+\kappa_{eg}, \frac{8\kappa_{ef}}{\kappa_{fcd}(1-\eta_1)}+\kappa_{eg}}=:\hat{\xi}, 
\end{equation}
inspired by the proof of Theorem~\ref{liminfTheorem}, especially~\eqref{ineq4}. Then, following ~\cite{blanchet2016convergence} exactly, one can assume without loss of generality that $\depsilon=\gamma^i\delta_0$ for some integer $i=:j_{\epsilon}\leq 0$, whence $\Dk=\gamma^{{\ubar{i}}_k}\depsilon$ for any $k$ and some integer~${\ubar{i}}_k$.

