\begin{lemma}\label{partialMeasurable}
Any partial derivative 
$\frac{\partial f}{\partial x^i}: \left(\rn, \mathscr{B}(\rn)\right)\to \left(\R, \mathscr{B}(\R)\right),\ i\in\intbracket{1,n} $,
of a differentiable function $f$ is a Borel measurable function.
\end{lemma}

\begin{proof}
Let $(\bm{e_1},\bm{e_2},\dots,\bm{e_n})$ be the canonical basis of $\rn$. For any $i\in\intbracket{1,n} $ and $\bm{x}=(x^1,x^2,\dots,x^n)$, define, for all $j\in\N$,
$D_{ij}(\bm{x})=\frac{f(\bm{x}+h_j\bm{e_i})-f(\bm{x})}{h_j}$,
where $\accolade{h_j}_{j\in\N}$ is a sequence of positive real numbers converging to~$0$; $f$ is differentiable and hence continuous, and thus is Borel measurable~\cite[Theorem~13.2]{billingsley1995ThirdEdition}. Therefore, since for all $i\in\intbracket{1,n}$, $\underset{j\to\infty}{\lim}D_{ij}(\bm{x})=\frac{\partial f}{\partial x^i}(\bm{x}),$
then $\frac{\partial f}{\partial x^i}$ is also Borel measurable~\cite[Theorem~13.3 and Theorem~13.4-(ii)]{billingsley1995ThirdEdition}.
\end{proof}

\begin{lemma}\label{indicatorMeasurable}
Let $\zeta\geq 0$ be a constant, and consider the event $\Gamma_k:=\accolade{\Gk\geq 0}$, where $\Gk:=\normii{\QkRandomTranspose\nabla f(\Xk)}-\zeta\Dk$. Then $\Gk$, $\igk$, and $\igkc$ are $\fqalgebra$-measurable.
\end{lemma}

\begin{proof}
By construction, all the entries $\left(\QkRandom\right)_{ij},\ (i,j)\in\intbracket{1,n}\times\intbracket{1,p}$ of $\QkRandom$ are $\fqalgebra$-measurable, while $\Dk$ and the components $\Xk^i, \ i\in\intbracket{1, n}$ of $\Xk$ are $\falgebra$-measurable and hence $\fqalgebra$-measurable since $\falgebra\subseteq\fqalgebra$. Thus, for any $i\in\intbracket{1, n}$, $\frac{\partial f}{\partial x^i}(\Xk)$ is $\fqalgebra$-measurable as the composition of the Borel measurable function $\frac{\partial f}{\partial x^i}$ (from Lemma~\ref{partialMeasurable}) and the random map $\Xk:(\Omega,\fqalgebra)\to\left(\rn, \mathscr{B}(\rn)\right)$~\cite[Theorem~13.3 and Theorem~13.1-(ii)]{billingsley1995ThirdEdition}. Recall that  sums and products of measurable functions are also measurable~\cite[Theorem~13.3]{billingsley1995ThirdEdition}, 
%%consequence of Theorem~13.3
and note that the random variable 
\begin{equation}\label{ukRandomMeasurable}
\ubar{u}_k:=\normii{\QkRandomTranspose\nabla f(\Xk)}^2=\sum_{j=1}^p\left(\sum_{i=1}^n\left(\QkRandom\right)_{ij}\frac{\partial f}{\partial x^i}(\Xk) \right)^2 
\end{equation}
is consequently $\fqalgebra$-measurable. Thus $\Gk=\sqrt{{\ubar{u}_k}}-\zeta\Dk$ is also $\fqalgebra$-measurable. The $\fqalgebra$-measurability of $\Gk$ ensures in particular that $\Gamma_k=\Gk^{-1}([0, \infty))\in\fqalgebra$ since $[0, \infty)$ is a Borel set of $\R$, whence the {\it simple} real functions $\igk$ and $\igkc$~\cite[Equation~(13.3)]{billingsley1995ThirdEdition} are also $\fqalgebra$-measurable. 
\end{proof}

\begin{theorem}\label{zerothOrderScal}
Let all assumptions that were made in Lemmas~\ref{LemmaA}-\ref{LemmaD} hold with the same constants $C_1, C_2$, and $C_3:=C_3(\zeta)$, for some fixed $\zeta>0$ satisfying
\begin{equation}\label{zetaChoice}
\zeta\geq \kappa_{eg}+\max\accolade{\eta_2,\kappa_h, \frac{8\kappa_{ef}}{\kappa_{fcd}(1-\eta_1)}}.
\end{equation}
Let $\nu\in (0,1)$ be chosen according to 
\begin{equation}\label{nuChoiceScal}
\frac{\nu}{1-\nu} \geq \frac{8\gamma^2}{\min\accolade{C_2, \zeta C_1}}.  
\end{equation}
Assume further that Assumption~\ref{assumptionsOnEstimatesAndModels} holds with $\beta_f, \beta_m\in (0,1)$ satisfying\footnote{In~\eqref{probChoices}, the result is intentionally presented with $(1-\beta_f)+(1-\beta_m)$ instead of $2-\beta_f-\beta_m$ in order to emphasize one of its differences compared with~\cite{blanchet2016convergence,chen2018stochastic} in which a term similar to $(1-\beta_f)(1-\beta_m)$ was derived.}
\begin{equation}\label{probChoices}
\frac{\beta_f\beta_m-\frac{1}{2}}{(1-\beta_f)+(1-\beta_m)}\geq \frac{C_3}{C_1}\quad \mbox{ and }\quad \frac{\beta_f}{1-\beta_f}\geq \frac{2\nu\zeta\gamma^2C_3}{(1-\nu)(\gamma^2-1)}+2\gamma^2.
\end{equation}
Define $\varrho=\frac{1}{2}\beta_f(1-\nu)(1-\frac{1}{\gamma^2})>0$. Then, the random function $\Phik:=\nu (f(\Xk)-f_{\min})+(1-\nu)\Dk^2$ satisfies
\begin{equation}\label{PhikIncrementBound}
\E{\Phikun-\Phik|\fqalgebra}\leq -\varrho\Dk^2 \quad \mbox{for all}\ k\in\N,
\end{equation}
which implies that
\begin{equation}\label{seriesResult}
\sum_{k=0}^{\infty}\Dk^2<\infty\quad \mbox{almost surely.}
\end{equation}
\end{theorem}

\begin{proof}
The proof is inspired by those of~\cite[Theorem~3]{blanchet2016convergence} and~\cite[Theorem~4.11]{chen2018stochastic}. 
The overall goal is to prove~\eqref{PhikIncrementBound}. Indeed noticing that $\Phik>0$ and then taking expectations on both sides of the inequality in~\eqref{PhikIncrementBound}, we obtain~\eqref{seriesResult} (see, e.g.,~\cite[Theorem~3]{dzahini2020expected} for details). Let $\phi_k$ denote realizations of $\Phik$, and recall that on all successful iterations, $\xkun=\xk+\Qk\sk$ and $\dkun=\min\accolade{\gamma\dk,\dmaxx}$,  implying
\begin{equation}\label{un}
\phi_{k+1}-\phi_k\leq \nu\left(f(\xkun)-f(\xk)\right)+(1-\nu)(\gamma^2-1)\dk^2,
\end{equation}
while on unsuccessful iterations, $\xkun=\xk$ and $\dkun=\gamma^{-1}\dk$, in which case
\begin{equation}\label{bOne}
\phi_{k+1}-\phi_k\leq(1-\nu)\left(\frac{1}{\gamma^2}-1\right)\dk^2=:b_1<0.
\end{equation}

Recall the event $\Gamma_k=\accolade{\normii{\QkRandomTranspose\nabla f(\Xk)}\geq\zeta\Dk}$ of Lemma~\ref{indicatorMeasurable} with $\zeta$ satisfying ~\eqref{zetaChoice}. The proof considers two cases: $\igk=1$ and $\igkc=1$. Inspired by~\cite[proof of Theorem~4.11]{chen2018stochastic}, Case~1 aims to show that
\begin{equation}\label{huit}
%\begin{split}
\E{\igk\left(\Phikun-\Phik\right)|\fqalgebra}\leq-2\igk(1-\nu)(\gamma^2-1)\Dk^2
\leq -\frac{1}{2}\igk\beta_f(1-\nu)(1-\frac{1}{\gamma^2})\Dk^2, 
%\end{split}
\end{equation}
where the last inequality follows from $1-\frac{1}{\gamma^2}<\gamma^2-1$ and $\beta_f\leq 1$. On the other hand, inspired by~\cite[proof of Theorem~3]{blanchet2016convergence}, Case~2 shows that
\begin{equation}\label{last}
\E{\igkc\left(\Phikun-\Phik\right)|\fqalgebra}\leq-\frac{1}{2}\igkc\beta_f(1-\nu)(1-\frac{1}{\gamma^2})\Dk^2.
\end{equation}
Thus, combining~\eqref{huit} and~\eqref{last} leads to~\eqref{PhikIncrementBound}.

$ $\\
\textbf{Case~1: $\igk=1$}\\
$ $\\
Unlike the proof of~\cite[Theorem~4.11, Case~1]{chen2018stochastic} where four subcases were considered, only three are analyzed next.

%\begin{itemize}
%\item[(i)] 
\noindent \textit{(Subcase 1i)}
Good model ($\iik=1$) and good estimates ($\ijk=1$). By~\eqref{zetaChoice}, 
\[\normii{\QkTranspose\nabla f(\xk)}\geq \max\accolade{\eta_2+\kappa_{eg}, \kappa_h+\kappa_{eg}, \frac{8\kappa_{ef}}{\kappa_{fcd}}+\kappa_{eg}}\dk,\]
implying in particular~\eqref{deltaLemmaB2} and hence a decrease in $f$ according to~\eqref{LemmaB2improvement}. Moreover, by $(\kef,\keg;\Qk)$-full linearity, 
\[\normii{\gkhat}\geq \normii{\QkTranspose\nabla f(\xk)}-\kappa_{eg}\dk\geq \max\accolade{\eta_2,\kappa_h, \frac{8\kappa_{ef}}{\kappa_{fcd}(1-\eta_1)}}\dk, \]
thus implying~\eqref{deltaLemmaC}; and since $\ef\leq \kappa_{ef}$ per assumptions of Lemma~\ref{LemmaC}, the iteration is successful. Consequently,~\eqref{un} together with~\eqref{LemmaB2improvement} yields
\begin{equation}\label{bTwo}
\begin{split}
	\phi_{k+1}-\phi_k &\leq -\nu C_1\normii{\QkTranspose\nabla f(\xk)}\dk+(1-\nu)(\gamma^2-1)\dk^2=:b_2\\
	&\leq \left(-\nu C_1\zeta+(1-\nu)(\gamma^2-1)\right)\dk^2<0,
\end{split}
\end{equation}
where the last inequality follows from~\eqref{nuChoiceScal}. Denoting by ${\ubar{b}}_2({\ubar{u}}_k,\Dk)$ the random variable with realizations $b_2<0$, with ${\ubar{u}}_k$ defined in~\eqref{ukRandomMeasurable}, we have from~\eqref{bTwo} that
\begin{equation}\label{bTwoRandom}
\igk\iik\ijk\left(\Phikun-\Phik\right)\leq \igk\iik\ijk{\ubar{b}}_2({\ubar{u}}_k,\Dk).
\end{equation}
%\item[(ii)] 
\noindent \textit{(Subcase 1ii)}
Bad model ($\iikc=1$) and good estimates ($\ijk=1$). In this case, regardless of the iteration type (i.e., successful or unsuccessful), the change in $\phi_k$ can always be bounded by using~\eqref{un} and~\eqref{LemmaEincrease} as follows:
\begin{equation}\label{bThree}
\phi_{k+1}-\phi_k\leq\nu C_3\norme{\QkTranspose\nabla f(\xk)}\dk+(1-\nu)(\gamma^2-1)\dk^2=:b_3.
\end{equation}
Denoting by ${\ubar{b}}_3({\ubar{u}}_k,\Dk)$ the random variable with realizations $b_3>0$, from~\eqref{bThree} we have that
\begin{equation}\label{bThreeRandom2}
\igk\iikc\ijk\left(\Phikun-\Phik\right)\leq \igk\iikc\ijk{\ubar{b}}_3({\ubar{u}}_k,\Dk)\leq \igk\iikc{\ubar{b}}_3({\ubar{u}}_k,\Dk).
\end{equation}
%\item[(iii)] 
\noindent \textit{(Subcase 1iii)}
Bad estimates ($\ijkc=1$). From \textit{Subcase 1ii}, it always holds that 
\begin{equation}\label{bThreeRandom3}
\igk\ijkc\left(\Phikun-\Phik\right)\leq \igk\ijkc{\ubar{b}}_3({\ubar{u}}_k,\Dk).
\end{equation}
%\end{itemize}

With the subcases thus complete, since the random variables $\igk, {\ubar{b}}_2({\ubar{u}}_k,\Dk)$, and ${\ubar{b}}_3({\ubar{u}}_k,\Dk)$ are $\fqalgebra$-measurable thanks to the proof of Lemma~\ref{indicatorMeasurable}, combining~\eqref{bTwoRandom},~\eqref{bThreeRandom2}, and~\eqref{bThreeRandom3} and taking expectations with respect to $\fqalgebra$, we have
\begin{equation}\label{bTwoThree}
\begin{split}
\E{\igk\left(\Phikun-\Phik\right)|\fqalgebra}&\leq \igk{\ubar{b}}_2({\ubar{u}}_k,\Dk)\E{\iik\ijk|\fqalgebra}\\
&+\igk{\ubar{b}}_3({\ubar{u}}_k,\Dk)\left(\E{\iikc|\fqalgebra}+\E{\ijkc|\fqalgebra}\right)\\
&\leq \igk\left(\beta_f\beta_m{\ubar{b}}_2({\ubar{u}}_k,\Dk)+{\ubar{b}}_3({\ubar{u}}_k,\Dk)(1-\beta_m+1-\beta_f)\right)=:\igk {\ubar{b}}_{2,3}({\ubar{u}}_k,\Dk),
\end{split}
\end{equation}
where the last inequality follows from~\eqref{ikQProb} and~\eqref{prodBetafBetam} and the fact that ${\ubar{b}}_2({\ubar{u}}_k,\Dk)<0$ while ${\ubar{b}}_3({\ubar{u}}_k,\Dk)>0$.  Note that 
\begin{eqnarray*}
{\ubar{b}}_{2,3}({\ubar{u}}_k,\Dk)&=&\nu \normii{\QkRandomTranspose\nabla f(\Xk)}\Dk\left[-\beta_f\beta_m C_1+(2-\beta_f-\beta_m)C_3\right]\\
& &+(1-\nu)(\gamma^2-1)(2-\beta_f-\beta_m+\beta_f\beta_m)\Dk^2\\
&\leq& \nu \normii{\QkRandomTranspose\nabla f(\Xk)}\Dk\left[-\beta_f\beta_m C_1+(2-\beta_f-\beta_m)C_3\right] + 2(1-\nu)(\gamma^2-1)\Dk^2,
\end{eqnarray*}
where the last inequality follows from $2-\beta_f-\beta_m+\beta_f\beta_m=1+(1-\beta_f)(1-\beta_m)\leq 2$.

For $\beta_f$ and $\beta_m$ chosen according to the first condition in~\eqref{probChoices}, and for $\nu$ satisfying~\eqref{nuChoiceScal}, the following holds:
\[\beta_f\beta_m C_1 - (2-\beta_f-\beta_m)C_3\geq \frac{1}{2}C_1\geq 2\frac{2(1-\nu)(\gamma^2-1)}{\nu\zeta}.\]
Hence, since $\normii{\QkRandomTranspose\nabla f(\Xk)}\geq \zeta\Dk$, then 
\begin{eqnarray*}
{\ubar{b}}_{2,3}({\ubar{u}}_k,\Dk)&\leq& -\frac{1}{2}\left[\beta_f\beta_m C_1-(2-\beta_f-\beta_m)C_3\right]\nu \normii{\QkRandomTranspose\nabla f(\Xk)}\Dk\\
&\leq& -\frac{1}{4}C_1\nu \normii{\QkRandomTranspose\nabla f(\Xk)}\Dk\leq -2(1-\nu)(\gamma^2-1)\Dk^2,
\end{eqnarray*}
which, together with~\eqref{bTwoThree}, leads to~\eqref{huit}.

$ $\\
\textbf{Case~2: $\igkc=1$}
$ $\\ 
Consider the event $G_k:=\accolade{\normii{\Gkhat}\geq \eta_2\Dk}$, and note that since $\Mhatk:={\ubar{f}_k}+\Gkhat^{\top}\sRandom +\frac{1}{2}\sRandom^{\top}\HkhatRandom\sRandom$ is $\fmqalgebra$-measurable by construction, then in particular $\normii{\Gkhat}$ and hence $\igkhat, \igkhatc$ are also $\fmqalgebra$-measurable. Observe that if $\igkhatc=1$, then the iteration is unsuccessful since $\normii{\gkhat}<\eta_2\dk$, leading to~\eqref{bOne}. Hence, 
\begin{equation}\label{GkbarCase2}
\begin{split}
\E{\igkc\igkhatc(\Phikun-\Phik)|\fmqalgebra}&\leq -(1-\nu)\left(1-\frac{1}{\gamma^2}\right)\E{\igkc\igkhatc\Dk^2|\fmqalgebra}\\
&\leq -\frac{1}{2}\igkc\igkhatc\beta_f(1-\nu)\left(1-\frac{1}{\gamma^2}\right)\Dk^2,
\end{split}
\end{equation}
where the last inequality is due to the $\fmqalgebra$-measurability of $\igkc$ and $\Dk$, given that $\falgebra\subset\fqalgebra\subset\fmqalgebra$. 

Inspired by~\cite[Theorem~3]{blanchet2016convergence}, which improved on the proof of~\cite[Theorem~4.11, Case~2]{chen2018stochastic} in which four subcases were considered, only two are analyzed next. The overall goal is to prove that
\begin{equation}\label{GkCase2}
\E{\igkc\igkhat(\Phikun-\Phik)|\fmqalgebra}\leq -\frac{1}{2}\igkc\igkhat\beta_f(1-\nu)\left(1-\frac{1}{\gamma^2}\right)\Dk^2,
\end{equation}
which, combined with~\eqref{GkbarCase2}, leads to 
\begin{equation*}%\label{GammaBarFmq}
\E{\igkc(\Phikun-\Phik)|\fmqalgebra}\leq -\frac{1}{2}\igkc\beta_f(1-\nu)\left(1-\frac{1}{\gamma^2}\right)\Dk^2
\end{equation*}
and consequently
\begin{equation*}%\label{GammaBarFq}
\begin{split}
\E{\igkc(\Phikun-\Phik)|\fqalgebra}&=\E{\E{\igkc(\Phikun-\Phik)|\fmqalgebra}|\fqalgebra}\\
&\leq \E{-\frac{1}{2}\igkc\beta_f(1-\nu)\left(1-\frac{1}{\gamma^2}\right)\Dk^2 \, |\fqalgebra}=-\frac{1}{2}\igkc\beta_f(1-\nu)\left(1-\frac{1}{\gamma^2}\right)\Dk^2,
\end{split}
\end{equation*}
 showing~\eqref{last}, where the last equality follows from the $\fqalgebra$-measurability of $\igkc$ and $\Dk$.  What remains to be shown is~\eqref{GkCase2} as achieved next, assuming that $\igkhat=1$.

\noindent \textit{(Subcase 2i)}
%\begin{itemize}
%\item[(i)] 
Good estimates ($\ijk=1$) and $\igkhat=1$. While $f$ is decreased on successful iterations because  of good estimates thanks to Lemma~\ref{LemmaD} and in this case~\eqref{LemmaDimprovement} holds,  $\dk$ is reduced on unsuccessful iterations, leading to~\eqref{bOne}. However, combining~\eqref{LemmaDimprovement} and~\eqref{un} yields
$\phi_{k+1}-\phi_k\leq \left[-\nu C_2+(1-\nu)(\gamma^2-1)\right]\dk^2\leq b_1,$
where the last inequality is due to~\eqref{nuChoiceScal}, which shows that~\eqref{bOne} holds in any case. Consequently,
\begin{equation}
\label{GammakBarGkJk}
\igkc\igkhat\ijk(\Phikun-\Phik) \leq -\igkc\igkhat\ijk(1-\nu)\left(1-\frac{1}{\gamma^2}\right)\Dk^2.
\end{equation}

%\item[(ii)] 
\noindent \textit{(Subcase 2ii)}
Bad estimates ($\ijkc=1$) and $\igkhat=1$. In this case, a successful step can lead to an increase in $f$
according to~\eqref{LemmaEincrease}, which combined with~\eqref{un} yield~\eqref{bThree} and hence
\begin{equation}\label{GammakBarGkJkBar}
\igkc\igkhat\ijkc(\Phikun-\Phik) \leq -\igkc\igkhat\ijkc\left(\nu C_3\zeta+(1-\nu)(\gamma^2-1)\right)\Dk^2.
\end{equation}
%\end{itemize}

With the subcases complete, recall that $\E{\ijk|\fmqalgebra}\geq\beta_f$. Then  combining~\eqref{GammakBarGkJk} and~\eqref{GammakBarGkJkBar} and taking expectations with respect to~$\fmqalgebra$ lead to
\begin{eqnarray*}%\label{GkCase2Proved}
\E{\igkc\igkhat(\Phikun-\Phik)|\fmqalgebra}&\leq& \igkc\igkhat\left(-\beta_f(1-\nu)(1-1/\gamma^2)\right.\\ 
& &\left. +\ (1-\beta_f)\left(\nu C_3\zeta+(1-\nu)(\gamma^2-1)\right) \right)\Dk^2\\
&\leq& -\frac{1}{2}\igkc\igkhat\beta_f(1-\nu)\left(1-\frac{1}{\gamma^2}\right)\Dk^2,
\end{eqnarray*}
thus proving~\eqref{GkCase2}, where the last inequality follows from the second condition in~\eqref{probChoices}, and the proof is complete.
\end{proof}

\begin{theorem}\label{liminfTheorem}
Let all the assumptions made in Theorem~\ref{zerothOrderScal} hold. Assume further that Assumption~\ref{wellAlignedAssumption} holds with $0\leq\beta_Q<1-\frac{1}{2\beta_f\beta_m}$. Then, the sequence $\accolade{\Xk}_{k\in\N}$ of random iterates generated by Algorithm~\ref{algoStoScalTR} satisfies
\[\underset{k\to\infty}{\liminf}\normii{\nabla f(\Xk)}=0\quad\mbox{ almost surely.}\]
\end{theorem}

\begin{proof}
The result is proved by contradiction conditioned on the almost sure event $E_0:=\accolade{\Dk\to 0}$ (thanks to Theorem~\ref{zerothOrderScal}), inspired by the proof of~\cite[Theorem~4.16]{chen2018stochastic} and also using ideas from~\cite{audet2019stomads,dzahini2020constrained}. Assume that with nonzero probability there exists a random variable ${\ubar{\varepsilon}}'>0$ such that 
$\normii{\nabla f(\Xk)}\geq {\ubar{\varepsilon}}' \mbox{ for all } k\in\N.$

Let $\accolade{\xk}, \accolade{\dk}$, and ${{\varepsilon}}'$ be realizations of $\accolade{\Xk}, \accolade{\Dk}$, and ${\ubar{\varepsilon}}'$, respectively, for which $\normii{\nabla f(\xk)}\geq {{\varepsilon}}'$ for all $k$. Since $\dk\to 0$, there exists $k_0\in\N$ such that
\begin{equation}\label{bChoice}
\dk<b:=\alpha_Q\cdot\min\accolade{\frac{{{\varepsilon}}'}{2(\kappa_h+\kappa_{eg})}, \frac{{{\varepsilon}}'}{2(\eta_2+\kappa_{eg})}, \frac{{{\varepsilon}}'}{\frac{16\kappa_{ef}}{\kappa_{fcd}(1-\eta_1)}+2\kappa_{eg}}, \frac{\dmaxx}{\gamma}}
\end{equation}
for all $k\geq k_0$.
Let $\ubar{r}_k$ be the random variable with realizations $r_k=\log_{\gamma}\left(\frac{\dk}{b}\right)$. Then $r_k<0$ for all $k\geq k_0$. The main idea is to show that such realizations occur only with probability zero, leading to a contradiction. 

To prove that $\accolade{\ubar{r}_k}$ is a submartingale, recall the events $I^Q_k$ and $J^Q_k$ satisfying~\eqref{otherProbIneqs} and $\mathcal{A}_k$ satisfying~\eqref{Akineq}.
%$\prob{\mathcal{A}_k|\falgebra}\geq 1-\beta_Q$, 
%$\prob{I^Q_k|\falgebra}\geq\beta_m$ and  $\prob{J^Q_k|\falgebra}\geq\beta_f$, 
%where $\mathcal{F}_{k-1}^Q :=\sigma\left(\mathcal{A}_0,\mathcal{A}_1,\dots,\mathcal{A}_{k-1}\right)\cap \sigma\left(I^Q_0,I^Q_1,\dots,I^Q_{k-1}\right)\cap \sigma\left(J^Q_0,J^Q_1,\dots,J^Q_{k-1}\right)$. 
Consider some iteration $k\geq k_0$ for which $\mathcal{A}_k$, $I^Q_k$, and $J^Q_k$ all occur, which happens with probability at least $\beta_f\beta_m(1-\beta_Q)$ conditioned on $\falgebra$, as was shown in~\eqref{prodBetaIneq}. It follows from~\eqref{bChoice} that 
\begin{equation}\label{ineq4}
\normii{\nabla f(\xk)}\geq \frac{1}{\alpha_Q}\max\accolade{\kappa_h+\kappa_{eg}, \eta_2+\kappa_{eg}, \frac{8\kappa_{ef}}{\kappa_{fcd}(1-\eta_1)}+\kappa_{eg}}\dk,
\end{equation}
which, together with the $(\kef,\keg;\Qk)$-full linearity and $\alpha_Q$-well alignment, yield
\begin{equation}\label{ineq5}
%\begin{split}
\normii{\gkhat}\geq\normii{\QkTranspose\nabla f(\xk)}-\kappa_{eg}\dk\geq \alpha_Q \normii{\nabla f(\xk)}-\kappa_{eg}\dk
\geq \max\accolade{\kappa_h, \eta_2, \frac{8\kappa_{ef}}{\kappa_{fcd}(1-\eta_1)}}\dk.
%\end{split}
\end{equation}
Thus, the $k$th iteration is successful according to Lemma~\ref{LemmaC}. Hence, $\dkun=\gamma\dk$, and hence $r_{k+1}=r_k+1$. For all other outcomes of $\mathcal{A}_k$, $I^Q_k$, and $J^Q_k$, which occur with a total probability of at most $1-\beta_f\beta_m(1-\beta_Q)$, it always holds that $\dkun\geq\gamma^{-1}\dk$, which implies that $r_{k+1}\geq r_k-1$. Hence, 
\begin{eqnarray*}
\E{\mathds{1}_{\mathcal{A}_k\cap I^Q_k\cap J^Q_k} \left(\ubar{r}_{k+1}-\ubar{r}_k\right)|\falgebra}&\geq& \beta_f\beta_m(1-\beta_Q)\quad \quad\mbox{and}\\
\E{\mathds{1}_{\overline{\mathcal{A}_k\cap I^Q_k\cap J^Q_k}} \left(\ubar{r}_{k+1}-\ubar{r}_k\right)|\falgebra}&\geq& \beta_f\beta_m(1-\beta_Q)-1, 
\end{eqnarray*}
which shows that $\accolade{\ubar{r}_k}$ is a submartingale if $0\leq\beta_Q<1-\frac{1}{2\beta_f\beta_m}$.

Using the random walk defined in~\eqref{randomWalk}, one  can easily  show (following, e.g.,~\cite[Theorem~4]{audet2019stomads}, \cite[Theorem~4.16]{chen2018stochastic} and~\cite[Theorem~3.6 and Lemmas~4.7 and~4.12]{dzahini2020constrained}) that $\accolade{\ubar{w}_k}$ is also a submartingale with bounded increments and, as such, cannot converge to a finite value, and therefore $\prob{\underset{k\to\infty}{\limsup}\ \ubar{w}_k=\infty}=1$ (thanks to~\cite[Theorem~4.4]{chen2018stochastic}). However, since $r_k-r_{k_0}\geq w_k-w_{k_0}$ by construction,  the sequence of realizations~$r_k$ such that $r_k<0\ \forall k\ \geq k_0$ occurs with probability zero, leading to a contradiction, which achieves the proof.
\end{proof}

\begin{lemma}\label{smallLemma}
Let all the assumptions made in Theorem~\ref{liminfTheorem} hold. Then~\eqref{dynamicsRenewal} is satisfied for\\ $\Wtildek=2\left(\iak\iik\ijk-\frac{1}{2} \right)$, with $\lambda=\ln(\gamma)$ and some fixed $q\in (\tilde{\beta}, 1)$ with $\tilde{\beta}=\beta_f\beta_m(1-\beta_Q)$.
\end{lemma}

\begin{proof}
The result is proved by suitably adapting the proof of~\cite[Lemma~7]{blanchet2016convergence} as was done in~\cite{dzahini2020expected}. First, we notice that~\eqref{dynamicsRenewal} trivially holds when $\itksup=0$. Next, we show that when $\itksup=1$, then 
\[\Dkun\geq \min\accolade{\depsilon, \min\accolade{\dmaxx,\gamma\Dk}\iak\iik\ijk+\gamma^{-1}\Dk\left(1-\iak\iik\ijk\right)}. \]
Recall that $\dk=\gamma^{i_k}\depsilon$ for some integer $i_k$. Therefore, if $\dk>\depsilon$, then $\dk\geq \gamma\depsilon$, which implies that $\dkun\geq\gamma^{-1}\dk\geq\depsilon$. Now assume that $\dk\leq \depsilon$. Since $\tauEpsilon>k$, we have $\normii{\nabla f(\xk)}>\epsilon=\xi\depsilon\geq\xi\dk$. Thus, it follows from the definition of~$\xi$ that~\eqref{ineq4} holds. If $\iak=1$, $\iik=1$, and $\ijk=1$, then~\eqref{ineq5} holds, and consequently the $k$th iteration is successful, as was  explained in the proof of Theorem~\ref{liminfTheorem}. Hence, $\xkun=\xk+\Qk\sk$ and $\dkun=\min\accolade{\dmaxx,\gamma\dk}$. If $\iak\iik\ijk=0$, then it always holds that $\dkun\geq \gamma^{-1}\dk$. The proof is completed by  observing that $\prob{\iak\iik\ijk=1}=q$ for some fixed $q\geq \tilde{\beta}$.
\end{proof}

\begin{proof}
Recall the choice of $q$ in Lemma~\ref{smallLemma}, and pick some $\tilde{\xi}\geq\hat{\xi}$ such that $\depsilon=\frac{\epsilon}{\tilde{\xi}}=\gamma^{i}\delta_0$ for some integer $i\leq 0$ (without loss of generality), as discussed above. The proof follows by employing Theorem~\ref{theorComplexity1} with $h(t)=t^2$, which yields
\[\E{\tauEpsilon}\leq \frac{q}{2q-1}\cdot\frac{\PhiZero\tilde{\xi}^2}{\varrho \epsilon^2}+1\leq \frac{\tilde{\beta}}{2\tilde{\beta}-1}\cdot\frac{\PhiZero\tilde{\xi}^2}{\varrho \epsilon^2}+1.\]
\end{proof}

 egin{proof}
The proof is similar to that of~\cite[Lemma~4.5]{chen2018stochastic} and is not detailed here. It follows from~\eqref{CauchyDecrease} together with the inequalities $\kappa_h\geq \max\accolade{
orme{\Hkhat}, 1}$ and $
ormii{\gkhat}\geq\kappa_h\dk$ that  $\mhatk( m{0})-\mhatk(\sk)\geq rac{\kappa_{fcd}}{2}
