\end{proof}

\begin{proof}
The proof is inspired by (and similar to) that of~\cite[Lemma~4.6]{chen2018stochastic}. By $(\kef,\keg;\Qk)$-full linearity and~\eqref{deltaLemmaB2}, it holds
\begin{equation}\label{ineq1}
\normii{\gkhat}\geq \normii{\QkTranspose\nabla f(\xk)}-\kappa_{eg}\dk\geq \max\accolade{\kappa_h, \frac{8\kappa_{ef}}{\kappa_{fcd}}}\dk, 
\end{equation}
which shows that condition~\eqref{LemmaAimprovement} is satisfied. Consequently $f$ decreases as in~\eqref{LemmaAimprovement}. The first inequality in~\eqref{ineq1}, together with~\eqref{deltaLemmaB2}, yields
$\normii{\gkhat}\geq \frac{4C_1}{\kappa_{fcd}}\normii{\QkTranspose\nabla f(\xk)},$
which, combined with~\eqref{LemmaAimprovement}, implies~\eqref{LemmaB2improvement}, and the proof is complete.
\end{proof}

